1.1 Passing network adjacency matrix for each team in each game，matlab
da=xlsread('aaa.xlsx',1,'C2:D366'); N=14;
from=da(:,1);to=da(:,2); A=zeros(N);sum=0; for m=1:N       for n=1:N
   for i=1:length(from)

      if (from(i)==m)&&(to(i)==n)
        sum=sum+1;
      end

   end
 A(m,n)=sum;sum=0;
 end
end
xlswrite('H1 adjacency matrix.xlsx',A);

